import axios from "axios";

const TENOR_KEY = process.env.REACT_APP_TENOR_KEY;

// API nova do Tenor (Google)
const BASE = "https://tenor.googleapis.com/v2";

export async function searchGifs(query, { limit = 24, pos = null } = {}) {
  if (!TENOR_KEY) {
    throw new Error("Tenor API key not configured. Set REACT_APP_TENOR_KEY in .env");
  }

  const params = {
    key: TENOR_KEY,
    q: query || "trending",
    limit,
    media_filter: "gif",   // somente GIF
  };

  if (pos) params.pos = pos;

  const url = `${BASE}/search`;
  const res = await axios.get(url, { params });

  return {
    results: res.data?.results || [],
    next: res.data?.next || null,
  };
}

export async function trendingGifs({ limit = 24, pos = null } = {}) {
  if (!TENOR_KEY) {
    throw new Error("Tenor API key not configured. Set REACT_APP_TENOR_KEY in .env");
  }

  const params = {
    key: TENOR_KEY,
    limit,
    media_filter: "gif",
  };

  if (pos) params.pos = pos;

  const url = `${BASE}/featured`;  // “trending” virou “featured” no v2
  const res = await axios.get(url, { params });

  return {
    results: res.data?.results || [],
    next: res.data?.next || null,
  };
}
